import sys
from itertools import permutations


def main():
    data = sys.stdin.read().split()
    n, m, s, t = int(data[0]), int(data[1]), int(data[2]), int(data[3])
    edges = set()
    idx = 4
    for _ in range(m):
        edges.add((int(data[idx]), int(data[idx + 1])))
        idx += 2
    if s == t:
        print(s)
        return
    others = [x for x in range(1, n + 1) if x != s and x != t]
    best = None
    for k in range(len(others) + 1):
        for mid in permutations(others, k):
            path = [s, *mid, t]
            if all((path[i], path[i + 1]) in edges for i in range(len(path) - 1)):
                if best is None or path < best:
                    best = path
    if best is None:
        print(-1)
    else:
        print(' '.join(map(str, best)))


main()
